(async function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={audits:[],importRecord:null,verification:null,implementation:[],staging:[],defects:[],rcGates:[]};
const sorted=a=>(a||[]).slice().sort((x,y)=>Date.parse(y?.at||y?.payload?.approvedAt||y?.payload?.testedAt||y?.payload?.recordedAt||0)-Date.parse(x?.at||x?.payload?.approvedAt||x?.payload?.testedAt||x?.payload?.recordedAt||0));
const rowsByType=t=>state.audits.filter(x=>x?.type===t).map(x=>x.payload||x).filter(Boolean);const latest=rows=>JK_PHASE41.latest(rows);const hashFile=async f=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');
function badgeClass(v){return ['PASS','PLAN_APPROVED','GUARDRAIL_PASS','STAGING_PASS','IMPLEMENTATION_EVIDENCE_RECORDED','ROLLBACK_REHEARSAL_PASS','RC_APPROVED','CLOSED','REVERIFY_PASS'].includes(v)?'PASS':['FAIL','STAGING_FAIL','IMPLEMENTATION_EVIDENCE_REJECTED','RC_BLOCKED','OPEN','TRIAGED','REVERIFY_REQUIRED'].includes(v)?'FAIL':'NOT_RUN'}
function render(){const v=state.verification||{status:'NOT_IMPORTED'},coverage=JK_PHASE41.implementationCoverage(v,state.implementation),s=latest(state.staging)||{status:'NOT_RUN'},g=latest(state.rcGates)||{status:'NOT_RECORDED'};for(const [id,val] of [['phase41InputBadge',v.status],['phase41PlanBadge',v.plan?.status||'NOT_VERIFIED'],['phase41GuardrailBadge',v.guardrail?.status||'NOT_VERIFIED'],['phase41Phase40StagingBadge',v.phase40Staging?.status||'NOT_VERIFIED'],['phase41ImplBadge',coverage.complete?'COMPLETE':state.implementation.length?'INCOMPLETE':'NOT_RECORDED'],['phase41CandidateStagingBadge',s.status],['phase41RollbackBadge',s.rollbackRehearsal?.status||'NOT_RUN'],['phase41RcBadge',g.status]])if($(id)){$(id).textContent=val;$(id).className=`status ${badgeClass(val==='COMPLETE'?'PASS':val)}`};if($('phase41SourceSha'))$('phase41SourceSha').textContent=v.bundleSha256||'-';if($('phase41RequestId')){$('phase41RequestId').innerHTML='<option value="">Select authorized request</option>'+(v.requestIds||[]).map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('')};if($('phase41ImplementationList'))$('phase41ImplementationList').innerHTML=(v.requestIds||[]).map(id=>{const rec=state.implementation.find(x=>x.requestId===id&&x.accepted);return `<div class="decisionRow"><div><strong>${esc(id)}</strong><div class="note">${rec?esc(rec.builtArtifactRef):'implementation evidence required'}</div></div><span class="status ${badgeClass(rec?.status||'NOT_RECORDED')}">${esc(rec?.status||'NOT_RECORDED')}</span></div>`}).join('')||'<div class="note">No verified Phase 40 requests.</div>';if($('phase41DefectList'))$('phase41DefectList').innerHTML=state.defects.slice(0,8).map(d=>`<div class="decisionRow"><div><strong>${esc(d.defectId)} · ${esc(d.severity)}</strong><div class="note">${esc(d.summary)}</div></div><span class="status ${badgeClass(d.status)}">${esc(d.status)}</span></div>`).join('')||'<div class="note">No Phase 41 defects recorded.</div>';if($('phase41Export'))$('phase41Export').disabled=!state.importRecord}
async function load(){state.audits=sorted(await JK_STORAGE.listApprovalAudit());state.importRecord=rowsByType('phase41_phase40_audit_import_saved')[0]||null;state.verification=state.importRecord?.verification||null;state.implementation=rowsByType('phase41_implementation_evidence_saved');state.staging=rowsByType('phase41_candidate_staging_saved');state.defects=rowsByType('phase41_defect_saved');state.rcGates=rowsByType('phase41_rc_gate_saved');render()}
async function verifyBundle(){const file=$('phase41BundleFile').files?.[0];if(!file){$('phase41ImportMessage').textContent='Select a Phase 40 audit JSON.';return}try{const bundle=JSON.parse(await file.text()),sha=await hashFile(file),verification=JK_PHASE41.verifyPhase40AuditBundle(bundle,{computedSha256:sha,expectedSha256:$('phase41ExpectedSha').value}),record={format:'JK_ENG_PHASE41_PHASE40_AUDIT_IMPORT',version:'41.0',importId:verification.verificationId,phase40Bundle:bundle,phase40BundleMeta:{name:file.name,size:file.size,lastModified:file.lastModified,sha256:sha,expectedSha256:JK_PHASE41.normalizeHash($('phase41ExpectedSha').value)||null},verification,importedAt:new Date().toISOString()};await JK_STORAGE.appendApprovalAudit({type:'phase41_phase40_audit_import_saved',entityId:record.importId,payload:record});$('phase41ImportMessage').textContent=verification.status==='PASS'?'Phase 40 plan, guardrail, and actual staging verified. Implementation evidence is still required.':'Verification failed: '+verification.errors.join(', ');await load()}catch(e){$('phase41ImportMessage').textContent='Import failed: '+(e.message||e)}}
async function saveImplementation(){let sha=$('phase41ImplArtifactSha').value;const f=$('phase41ImplArtifactFile').files?.[0];if(f)sha=await hashFile(f);const rec=JK_PHASE41.recordImplementationEvidence({requestId:$('phase41RequestId').value,implementedBy:$('phase41ImplementedBy').value,evidence:$('phase41ImplEvidence').value,builtArtifactRef:$('phase41ImplArtifactRef').value||f?.name,builtArtifactSha256:sha},state.verification||{});if(!rec.accepted){$('phase41ImplMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase41_implementation_evidence_saved',entityId:rec.evidenceId,payload:rec});$('phase41ImplMessage').textContent='Implementation evidence recorded. No automatic application occurred.';await load()}
async function saveStaging(){const ids=['AUTH','DAILY_LOOP','MULTI_DEVICE_RESUME','OFFLINE_RECOVERY','ADMIN_RECOVERY','ASSET_INTEGRITY','ROLLBACK_READINESS'],cases=ids.map(id=>({id,status:$(`phase41Stage${id}Status`).value,evidence:$(`phase41Stage${id}Evidence`).value}));let csha=$('phase41CandidateSha').value,msha=$('phase41ManifestSha').value;const cf=$('phase41CandidateFile').files?.[0],mf=$('phase41ManifestFile').files?.[0];if(cf)csha=await hashFile(cf);if(mf)msha=await hashFile(mf);const rec=JK_PHASE41.createCandidateStaging({actualStagingContext:$('phase41StagingActual').checked,stagingUrl:$('phase41StagingUrl').value,operator:$('phase41StagingOperator').value,candidateArtifactSha256:csha,assetManifestVersion:$('phase41ManifestVersion').value,assetManifestSha256:msha,cases,rollbackRehearsal:{actualRehearsal:$('phase41RollbackActual').checked,target:$('phase41RollbackTarget').value,result:$('phase41RollbackResult').value,operator:$('phase41RollbackOperator').value,evidence:$('phase41RollbackEvidence').value,restoreCandidateEvidence:$('phase41RollbackRestoreEvidence').value}},state.verification||{},state.implementation);await JK_STORAGE.appendApprovalAudit({type:'phase41_candidate_staging_saved',entityId:rec.runId,payload:rec});$('phase41StagingMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. Production deployment remains separate.`;await load()}
async function saveDefect(){const rec=JK_PHASE41.recordDefect({defectId:$('phase41DefectId').value,severity:$('phase41DefectSeverity').value,status:$('phase41DefectStatus').value,summary:$('phase41DefectSummary').value,evidence:$('phase41DefectEvidence').value});if(!rec.accepted){$('phase41DefectMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase41_defect_saved',entityId:rec.defectId,payload:rec});$('phase41DefectMessage').textContent='Defect state recorded.';await load()}
async function saveRcGate(){const preservations={processScoringPreserved:$('phase41PreserveProcess').checked,textbookReturnLoopPreserved:$('phase41PreserveTextbook').checked,evidenceMarkingPreserved:$('phase41PreserveEvidence').checked,originalRetryPreserved:$('phase41PreserveRetry').checked,nonAnxietyPacingPreserved:$('phase41PreservePacing').checked},impacts={numericCountdownVisible:$('phase41ImpactCountdown').checked,bypassProcessScoring:$('phase41ImpactProcessBypass').checked,bypassTextbookReturn:$('phase41ImpactTextbookBypass').checked,bypassEvidenceMarking:false,bypassOriginalRetry:false,automaticImplementation:false,automaticDeployment:false,automaticRollback:false,automaticPersonalizationThresholdChange:false,automaticContentApply:false};const rec=JK_PHASE41.createRCGate({operator:$('phase41RcOperator').value,evidence:$('phase41RcEvidence').value,confirmationPhrase:$('phase41RcConfirm').value,preservations,impacts,guardrailRegression:$('phase41GuardrailRegression').checked,contentApprovalMismatch:$('phase41ContentMismatch').checked,learningLoopInvariantRegression:$('phase41LoopRegression').checked},state.verification||{},state.implementation,latest(state.staging)||{},state.defects);await JK_STORAGE.appendApprovalAudit({type:'phase41_rc_gate_saved',entityId:rec.gateId,payload:rec});$('phase41RcMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. External v1.0.2 release remains NOT_RUN.`;await load()}
function downloadJson(payload,name){const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportAudit(){downloadJson(JK_PHASE41.buildPhase41AuditBundle({phase40BundleMeta:state.importRecord?.phase40BundleMeta||null,phase40AuditVerification:state.verification,implementationEvidence:state.implementation,candidateStagingRuns:state.staging,defects:state.defects,rcGates:state.rcGates}),`JK_ENG_Phase41_v102_Implementation_Staging_RC_${new Date().toISOString().slice(0,10)}.json`)}
await JK_AUTH.requireRole('admin');await JK_STORAGE.init();$('phase41VerifyBundle').onclick=verifyBundle;$('phase41ImplSave').onclick=saveImplementation;$('phase41StagingSave').onclick=saveStaging;$('phase41DefectSave').onclick=saveDefect;$('phase41RcSave').onclick=saveRcGate;$('phase41Export').onclick=exportAudit;await load();
})().catch(e=>{console.error(e);const el=document.getElementById('phase41ImportMessage');if(el)el.textContent=String(e.message||e)});
